private static <T> T checkConversionResult(Class<T> type, Object result) {
    if (type == null) {
        // If the type is null, return the result as-is
        @SuppressWarnings("unchecked")
        T temp = (T) result;
        return temp;
    }

    // Handle null result case
    if (result == null) {
        if (!type.isPrimitive()) {
            return null;
        }
        throw new ConversionException("Cannot convert null to a primitive type: " + type);
    }

    // Handle empty string result case
    if (result instanceof String && ((String) result).isEmpty()) {
        if (!type.isPrimitive()) {
            return null;
        }
        throw new ConversionException("Cannot convert empty string to a primitive type: " + type);
    }

    // Handle valid type case
    if (type.isInstance(result)) {
        return type.cast(result);
    }

    // If result is not of the expected type, throw exception
    throw new ConversionException("Unsupported target type: " + type);
}

